// Avinoam Studio Phase 1 reproducible source/build pack.
// No credentials: the browser key is intentionally publishable.
// node studio-build.mjs --extract writes editable sources into studio-source/.
// node studio-build.mjs builds dist/ without dependencies or paid services.
import {gunzipSync} from 'node:zlib';
import {readFileSync,writeFileSync,mkdirSync,cpSync,existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
const payload='';
const raw=gunzipSync(Buffer.from(payload,'base64'));
if(createHash('sha256').update(raw).digest('hex')!=='c48e81980df5112dce0752429fd60415b3704734a241d575552c88de9669cb56')throw Error('Source pack integrity check failed');
const files=JSON.parse(raw),extract=process.argv.includes('--extract'),out=extract?'studio-source':'dist';
mkdirSync(out,{recursive:true});
for(const [name,data] of Object.entries(files)){
 if(!extract&&(/-src[.]js$|[.]sql$|[.]md$|seed-content/.test(name)))continue;
 writeFileSync(out+'/'+name,Buffer.from(data,'base64'));
}
if(!extract){cpSync('portfolio',out+'/portfolio',{recursive:true});for(const name of ['10-avinoam-cutout.webp','11-studio-wall.svg'])cpSync(name,out+'/'+name);writeFileSync(out+'/index.html',readFileSync(out+'/studio-index.html'));writeFileSync(out+'/_headers','/studio-admin.html\n  Cache-Control: no-store\n/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: SAMEORIGIN\n');}
console.log(extract?'Editable sources extracted to studio-source/':'Built Avinoam Studio pilot in dist/');

